import{_ as a,o as s,c as n,a2 as t}from"./chunks/framework.DrWxItG4.js";const h=JSON.parse('{"title":"Login","description":"","frontmatter":{},"headers":[],"relativePath":"guide/login.md","filePath":"guide/login.md"}'),o={name:"guide/login.md"};function i(r,e,l,p,c,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="login" tabindex="-1">Login <a class="header-anchor" href="#login" aria-label="Permalink to &quot;Login&quot;">​</a></h1><p>This page covers what a private server needs: server_data.php and the ENet login that gurotopia and GrowServer accept. The official servers add a web login in between: a token from the login site, an <code>ltoken</code> message to a login server, then a redirect to a game server. That flow, as the 5.60 client runs it, is on <a href="/gtps-guide/guide/official-login">Login on the official servers</a>.</p><h2 id="_1-server-data-php-https" tabindex="-1">1. server_data.php (HTTPS) <a class="header-anchor" href="#_1-server-data-php-https" aria-label="Permalink to &quot;1. server_data.php (HTTPS)&quot;">​</a></h2><p>Before ENet, the client posts to <code>https://www.growtopia1.com/growtopia/server_data.php</code> (falling back to <code>www.growtopia2.com</code>) and reads:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server|192.168.1.10</span></span>
<span class="line"><span>port|17091</span></span>
<span class="line"><span>type|1</span></span>
<span class="line"><span>type2|1</span></span>
<span class="line"><span>#maint|Server under maintenance. Please try again later.</span></span>
<span class="line"><span>loginurl|login-gurotopia.vercel.app</span></span>
<span class="line"><span>meta|gurotopia</span></span>
<span class="line"><span>RTENDMARKERBS1001</span></span></code></pre></div><p>The 5.60 client also understands <code>beta_server</code>, <code>beta_port</code>, <code>beta_loginurl</code>, <code>beta_type</code> and <code>beta_maint</code> (plus <code>beta2_*</code> and <code>beta3_*</code>), which it uses after a server has put it in beta mode with <code>OnSetBetaMode</code>.</p><div class="warning custom-block"><p class="custom-block-title">The official Android app</p><p>Recent Android versions of the app only accept a certificate signed by a real authority for <code>www.growtopia1.com</code>, so they never get past this step on a private server. Your own client (<a href="/gtps-guide/guide/talk-to-server">Talk to the server</a>) skips HTTPS entirely: it already knows the address.</p></div><h2 id="_2-enet-login-gurotopia" tabindex="-1">2. ENet login, gurotopia <a class="header-anchor" href="#_2-enet-login-gurotopia" aria-label="Permalink to &quot;2. ENet login, gurotopia&quot;">​</a></h2><p><code>include/action/protocol.cpp</code> and <code>include/action/tankIDName.cpp</code>:</p><ol><li>Server → <a href="/gtps-guide/messages/1-server-hello">SERVER_HELLO</a>.</li><li>Client → <a href="/gtps-guide/messages/2-generic-text">GENERIC_TEXT</a>:<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>protocol|225</span></span>
<span class="line"><span>ltoken|&lt;base64 of &quot;growId=NAME&amp;password=PASS&quot;&gt;</span></span></code></pre></div>A GrowID that doesn&#39;t exist yet is created with that password (<code>peer::load()</code>).</li><li>Server → <a href="/gtps-guide/functions/OnSendToServer">OnSendToServer</a><code>(port, 0, user_id, &quot;ip|0|0&quot;, 1, growid)</code>.</li><li>Client → GENERIC_TEXT starting with <code>tankIDName|NAME</code>, containing <code>protocol|</code> (non-zero) and <code>user|&lt;user_id from step 3&gt;</code>. gurotopia schedules a disconnect if the message has fewer than 41 <code>|</code>-separated fields. The official client reconnects first; gurotopia also accepts it on the same connection.</li><li>Server → <code>OnOverrideGDPRFromServer</code>, <a href="/gtps-guide/functions/OnSuperMainStartAcceptLogonHrdxs47254722215a">OnSuperMainStartAcceptLogon…</a>.</li><li>Client → <a href="/gtps-guide/actions/enter_game">action|enter_game</a>.</li><li>Client → <a href="/gtps-guide/actions/join_request">action|join_request</a>.</li></ol><h2 id="_2-enet-login-growserver" tabindex="-1">2. ENet login, GrowServer <a class="header-anchor" href="#_2-enet-login-growserver" aria-label="Permalink to &quot;2. ENet login, GrowServer&quot;">​</a></h2><p><code>src/game/server/game-server.ts</code> and <code>src/game/player/auth.ts</code>:</p><ol><li>Server → SERVER_HELLO.</li><li>Client → text with <code>ltoken|&lt;base64(url-encoded _token=SESSION&amp;...)&gt;</code>. <code>SESSION</code> must be a session token from GrowServer&#39;s own login website; a GrowID and password alone aren&#39;t accepted.</li><li>Server → OnSendToServer with a one-time transfer token (valid 60 s), then disconnects.</li><li>Client reconnects and sends <code>tankIDName|</code>, <code>token|&lt;transfer token&gt;</code>, <code>user|&lt;player id&gt;</code>.</li><li>Server → OnSuperMainStartAcceptLogon….</li></ol><h2 id="the-client-s-login-messages-5-60" tabindex="-1">The client&#39;s login messages (5.60) <a class="header-anchor" href="#the-client-s-login-messages-5-60" aria-label="Permalink to &quot;The client&#39;s login messages (5.60)&quot;">​</a></h2><p>The <strong>ltoken message</strong> (client function <code>0x1805e08</code>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>protocol|{}</span></span>
<span class="line"><span>ltoken|{}</span></span>
<span class="line"><span>platformID|{}</span></span>
<span class="line"><span>rcdl|{}</span></span>
<span class="line"><span>adc|{}            (only with Apple consent)</span></span></code></pre></div><p>The <strong>full login message</strong> (<code>0x180145c</code>), fields in order:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tankIDName|  tankIDPass|  requestedName|  f|  protocol|  game_version|  fz|  cbits|  hash2|  vid|</span></span>
<span class="line"><span>aid|  gid|  meta|  rid|  platformID|  deviceVersion|  country|  hash|  mac|  user|  token|  doorID|</span></span>
<span class="line"><span>wk|  fhash|  GDPR|  player_age|  category|  totalPlaytime|  klv|  lmode|  reconnect|1  FCMToken|</span></span></code></pre></div><p><code>tr|</code> comes first when present. <code>user|</code> and <code>token|</code> echo what the server sent in OnSendToServer. gurotopia reads only <code>tankIDName</code>, <code>protocol</code>, <code>country</code> and <code>user</code>.</p><h2 id="what-the-server-sends-after-enter-game" tabindex="-1">What the server sends after enter_game <a class="header-anchor" href="#what-the-server-sends-after-enter-game" aria-label="Permalink to &quot;What the server sends after enter_game&quot;">​</a></h2><p>Captured from gurotopia with <a href="/gtps-guide/guide/talk-to-server">hello.cpp</a>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;- OnSendToServer</span></span>
<span class="line"><span>&lt;- OnOverrideGDPRFromServer</span></span>
<span class="line"><span>&lt;- OnSuperMainStartAcceptLogonHrdxs47254722215a</span></span>
<span class="line"><span>&lt;- OnConsoleMessage Welcome back, \`wclienttest\`\`. No friends are online.</span></span>
<span class="line"><span>&lt;- OnConsoleMessage</span></span>
<span class="line"><span>&lt;- OnConsoleMessage \`5Personal Settings active:\`\` \`#Can customize profile\`\`</span></span>
<span class="line"><span>&lt;- game packet 0x09 (79 bytes)            SEND_INVENTORY_STATE</span></span>
<span class="line"><span>&lt;- OnSetBux</span></span>
<span class="line"><span>&lt;- SetHasGrowID</span></span>
<span class="line"><span>&lt;- OnTodaysDate</span></span>
<span class="line"><span>&lt;- OnRequestWorldSelectMenu</span></span>
<span class="line"><span>&lt;- OnConsoleMessage Where would you like to go? (\`w1\`\` online)</span></span>
<span class="line"><span>&lt;- OnDialogRequest                        the gazette</span></span>
<span class="line"><span>&lt;- game packet 0x16 (60 bytes)            PING_REQUEST</span></span>
<span class="line"><span>&lt;- OnSetFeatureEnableFlags</span></span></code></pre></div>`,22)])])}const u=a(o,[["render",i]]);export{h as __pageData,u as default};
